        Fixture(GameController game,boolean madoka){this.game=game;this.madoka=madoka;base=new ElementalGrimoireChecks.Fixture(game,true);base.retain=true;owner=base.owner;other=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));require(other!=null,"real second participant");level=owner.level();savedOwner=new Snapshot(game,owner);savedOther=new Snapshot(game,other);attribution=new SauvojenMeditationChecks.Attribution(game,List.of(owner,other));ownerTeam=owner.getTeam();otherTeam=other.getTeam();skills=game.config().lbcSkills;limit=game.config().lbcTrinketLimit;base.initialize();at=owner.position();client=new ScheduledClient(game,owner);audience=new ScheduledClient(game,other);client.acknowledge();audience.acknowledge();for(var player:List.of(owner,other)){if(player.getTeam()!=null)game.server().getScoreboard().removePlayerFromTeam(player.getScoreboardName(),player.getTeam());player.getInventory().clearContent();player.removeAllEffects();player.setNoGravity(true);player.setDeltaMovement(Vec3.ZERO);player.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);player.setHealth(1000);player.setAbsorptionAmount(0);player.setInvulnerableTime(0);player.damageCooldownTime=0;player.getAbilities().invulnerable=false;game.items().mana().baseRegen(player,0);game.items().mana().boost(player,0);game.players().get(player.getUUID()).lbcSkill=0;}game.config().lbcSkills=true;game.config().lbcTrinketLimit=99;position(other,at.add(30,0,0),0,0);reward=game.server().getAdvancements().get(Identifier.parse("lbc:true_advancements/bows/madoka_bow"));require(reward!=null,"original Madoka advancement loaded");}
