    private static Fixture running;
    private static void start(GameController game,boolean madoka){require(running==null,"exclusive fixture");running=new Fixture(game,madoka);try{if(madoka)running.startMadoka();else running.startShulker();}catch(Throwable error){try{running.close();}finally{running=null;}throw error;}}
    public static void run(GameController game){start(game,false);}
    public static void runMadoka(GameController game){start(game,true);}
    public static void tick(GameController game){if(running==null)return;boolean madoka=running.madoka;try{if(running.step()){running.close();running=null;SkyWars2.LOGGER.info("[check] PASS {}",madoka?"madoka-bow":"special-bows");}}catch(Throwable error){try{running.close();}finally{running=null;}SkyWars2.LOGGER.error("[check] FAIL "+(madoka?"madoka-bow":"special-bows"),error);}}
